CREATE TABLE device_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope varchar(16) NOT NULL DEFAULT 'SYSTEM', owner_key varchar(64) NOT NULL DEFAULT 'system', code varchar(32) NOT NULL, name varchar(32) NOT NULL, sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (scope, code));